/* ------------------------------------------------------- role components
   What a supporting role is paid on, by first matching rule. */
function componentsFor(R, role, ctx){
  const rules = R.componentSets[role];
  const hit = rules.find(rule => {
    if (rule.when === "otherwise") return true;
    if (rule.when.field !== undefined) return !!ctx.plan[rule.when.field];
    return ctx.answers[rule.when.answer] === rule.when.is;
  });
  return hit.components;
}

/* -------------------------------------------------------------- evaluator
   Expressions are prefix arrays. A bare string is a field already derived, a
   number is itself, and everything else is an operator. Arguments are named
   rather than indexed so this file can hold no numeric literal but 0 and 1,
   which is the property json-check.js lints for. */
function evaluate(expr, ctx){
  /* null is a value, not an expression: it is what a field holds when the role
     it belongs to is not on this plan. */
  if (expr === null) return null;
  if (typeof expr === "number") return expr;
  if (typeof expr === "string"){
    if (!(expr in ctx.plan)) throw new Error("unknown field: "+expr);
    return ctx.plan[expr];
  }
  if (!Array.isArray(expr)) throw new Error("bad expression: "+JSON.stringify(expr));
  const [op, x, y, z] = expr;
  const args = expr.slice(1);
  const ev = v => evaluate(v, ctx);
  const R = ctx.rules;
  switch (op){
    case "answer":  return ctx.answers[x];
    case "lookup":  return R.tables[x][ctx.answers[y]];
    case "const":   return R.constants[x];
    case "str":     return x;
    case "+":       return args.reduce((s,v) => s + ev(v), 0);
    case "-":       return ev(x) - ev(y);
    case "*":       return args.reduce((s,v) => s * ev(v), 1);
    case "/":       return ev(x) / ev(y);
    case "max":     return Math.max(ev(x), ev(y));
    case "min":     return Math.min(ev(x), ev(y));
    case "round":   return Math.round(ev(x));
    case "ceil":    return Math.ceil(ev(x));
    case "floor":   return Math.floor(ev(x));
    case "if":      return ev(x) ? ev(y) : ev(z);
    case "eq":      return ev(x) === ev(y);
    case "in":      return y.includes(ev(x));
    case "not":     return !ev(x);
    case "and":     return args.every(v => !!ev(v));
    case "or":      return args.some(v => !!ev(v));
    case "gt":      return ev(x) >  ev(y);
    case "gte":     return ev(x) >= ev(y);
    case "truthy":  return !!ev(x);
    case "null":    return null;
    /* Role component weights. The CS expansion target comes off the book and
       the rate then pays that component in full at the target, which is the
       same identity the AE plan rests on. */
    case "weightExact": {
      const c = componentsFor(R, x, ctx).find(c2 => c2.label === ev(y));
      return c ? c.weight : 0;
    }
    case "weightPrefix": {
      const c = componentsFor(R, x, ctx).find(c2 => c2.label.startsWith(ev(y)));
      return c ? c.weight : 0;
    }
    case "weightsByKind": {
      const out = {};
      componentsFor(R, x, ctx).forEach(c => {
        out[c.kind] = (out[c.kind] || 0) + c.weight;
      });
      return out;
    }
    case "fn":
      if (x === "segPhrase"){
        const seg = ev(y);
        return R.text.segPhrase.replace("{article}", article(R, seg)).replace("{seg}", seg);
      }
      throw new Error("unknown fn: "+x);
    case "complexity": return complexityScore(R, ctx.answers);
    case "scenarios":  return scenarioRows(R, ctx.plan);
    default: throw new Error("unknown operator: "+op);
  }
}

